def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def sgn(a):
        return 1 if a > 0 else (-1 if a < 0 else 0)

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        best = corners[0]
        best_d = -1
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if d > best_d:
                best_d = d
                best = c
        return step_toward((sx, sy), best)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        best = None
        best_d = 10**9
        for t in targets:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if d < best_d:
                best_d = d
                best = (tx, ty)
        if best is not None:
            return step_toward((sx, sy), best)
        return step_away((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_d = 10**9
    for r in resources:
        rx, ry = pos(r, None)
        if rx is None:
            continue
        d = abs(rx - sx) + abs(ry - sy)
        if d < best_d:
            best_d = d
            best = (rx, ry)

    if best is not None:
        return step_toward((sx, sy), best)

    return step_away((sx, sy), (ox, oy))

